// Parent-only delivery between the source dialog and the existing Browser ground.
// No global DOM message listener and no credentials or generated bytes.
const listeners = new Set()
export const subscribePrivateBuildSelection = listener => { listeners.add(listener); return () => listeners.delete(listener) }
export function selectPrivateBuild(value) {
  let copied
  try { copied = JSON.parse(JSON.stringify(value)) } catch { return false }
  let accepted = false
  for (const listener of listeners) {
    try { accepted = listener(copied) === true || accepted } catch { /* A stale ground cannot prevent another current listener. */ }
  }
  return accepted
}
